//! File-system ABI shared by x86_64 and aarch64: `AT_*`, `fcntl`, mode bits,
//! `statx`, `iovec`, `pollfd`, `linux_dirent64`.
//!
//! `O_*` flags are NOT here: `O_DIRECTORY`, `O_NOFOLLOW`, `O_DIRECT` and
//! `O_LARGEFILE` differ between the arches (see `x86_64::OpenFlags` and
//! `aarch64::OpenFlags`, both generated by [`open_flags!`](crate::open_flags)).
//! The arch-independent bits are exported as `O_*` constants here.

use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};

pub const O_RDONLY: u32 = 0o0;
pub const O_WRONLY: u32 = 0o1;
pub const O_RDWR: u32 = 0o2;
pub const O_ACCMODE: u32 = 0o3;
pub const O_CREAT: u32 = 0o100;
pub const O_EXCL: u32 = 0o200;
pub const O_NOCTTY: u32 = 0o400;
pub const O_TRUNC: u32 = 0o1000;
pub const O_APPEND: u32 = 0o2000;
pub const O_NONBLOCK: u32 = 0o4000;
pub const O_NDELAY: u32 = O_NONBLOCK;
pub const O_DSYNC: u32 = 0o10000;
pub const O_ASYNC: u32 = 0o20000;
pub const O_NOATIME: u32 = 0o1000000;
pub const O_CLOEXEC: u32 = 0o2000000;
/// `__O_SYNC`; `O_SYNC` is `__O_SYNC | O_DSYNC`.
pub const O_SYNC_BIT: u32 = 0o4000000;
pub const O_SYNC: u32 = O_SYNC_BIT | O_DSYNC;
pub const O_PATH: u32 = 0o10000000;
/// `__O_TMPFILE`; `O_TMPFILE` is `__O_TMPFILE | O_DIRECTORY` (arch-specific).
pub const O_TMPFILE_BIT: u32 = 0o20000000;

/// Generate an `OpenFlags` bitflags type given the four arch-specific bits.
#[macro_export]
#[doc(hidden)]
macro_rules! open_flags {
    (direct = $direct:expr, largefile = $large:expr, directory = $dir:expr, nofollow = $nofollow:expr) => {
        $crate::__bitflags::bitflags! {
            /// `open`/`openat` flags for this architecture.
            #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
            pub struct OpenFlags: u32 {
                const WRONLY = $crate::fs::O_WRONLY;
                const RDWR = $crate::fs::O_RDWR;
                const CREAT = $crate::fs::O_CREAT;
                const EXCL = $crate::fs::O_EXCL;
                const NOCTTY = $crate::fs::O_NOCTTY;
                const TRUNC = $crate::fs::O_TRUNC;
                const APPEND = $crate::fs::O_APPEND;
                const NONBLOCK = $crate::fs::O_NONBLOCK;
                const DSYNC = $crate::fs::O_DSYNC;
                const ASYNC = $crate::fs::O_ASYNC;
                const DIRECT = $direct;
                const LARGEFILE = $large;
                const DIRECTORY = $dir;
                const NOFOLLOW = $nofollow;
                const NOATIME = $crate::fs::O_NOATIME;
                const CLOEXEC = $crate::fs::O_CLOEXEC;
                const SYNC = $crate::fs::O_SYNC;
                const PATH = $crate::fs::O_PATH;
                const TMPFILE = $crate::fs::O_TMPFILE_BIT | $dir;
            }
        }

        impl OpenFlags {
            /// Access mode (`O_RDONLY`, `O_WRONLY`, `O_RDWR`).
            pub const fn access_mode(self) -> u32 {
                self.bits() & $crate::fs::O_ACCMODE
            }
            pub const fn readable(self) -> bool {
                let m = self.access_mode();
                m == $crate::fs::O_RDONLY || m == $crate::fs::O_RDWR
            }
            pub const fn writable(self) -> bool {
                let m = self.access_mode();
                m == $crate::fs::O_WRONLY || m == $crate::fs::O_RDWR
            }
        }
    };
}

