/// `linux_dirent64` header layout: `d_ino` u64 @0, `d_off` i64 @8,
/// `d_reclen` u16 @16, `d_type` u8 @18, `d_name` @19 (NUL-terminated),
/// record padded to 8 bytes.
pub const DIRENT64_INO_OFFSET: usize = 0;
pub const DIRENT64_OFF_OFFSET: usize = 8;
pub const DIRENT64_RECLEN_OFFSET: usize = 16;
pub const DIRENT64_TYPE_OFFSET: usize = 18;
pub const DIRENT64_NAME_OFFSET: usize = 19;

/// Record length for a `linux_dirent64` with a name of `name_len` bytes.
pub const fn dirent64_reclen(name_len: usize) -> usize {
    (DIRENT64_NAME_OFFSET + name_len + 1 + 7) & !7
}

/// Serialise one `linux_dirent64` into `buf`. Returns the record length, or
/// `None` if it does not fit (caller returns what it has, or `EINVAL` if
/// nothing fit). Padding bytes are zeroed.
pub fn write_dirent64(
    buf: &mut [u8],
    ino: u64,
    off: i64,
    d_type: u8,
    name: &[u8],
) -> Option<usize> {
    let reclen = dirent64_reclen(name.len());
    if reclen > buf.len() || reclen > u16::MAX as usize {
        return None;
    }
    let rec = &mut buf[..reclen];
    rec[0..8].copy_from_slice(&ino.to_le_bytes());
    rec[8..16].copy_from_slice(&off.to_le_bytes());
    rec[16..18].copy_from_slice(&(reclen as u16).to_le_bytes());
    rec[18] = d_type;
    rec[19..19 + name.len()].copy_from_slice(name);
    rec[19 + name.len()..].fill(0);
    Some(reclen)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dirent() {
        assert_eq!(dirent64_reclen(1), 24);
        assert_eq!(dirent64_reclen(4), 24);
        assert_eq!(dirent64_reclen(5), 32);
        let mut buf = [0xffu8; 64];
        let n = write_dirent64(&mut buf, 7, 1, DT_REG, b"hello").unwrap();
        assert_eq!(n, 32);
        assert_eq!(&buf[0..8], &7u64.to_le_bytes());
        assert_eq!(&buf[16..18], &32u16.to_le_bytes());
        assert_eq!(buf[18], DT_REG);
        assert_eq!(&buf[19..25], b"hello\0");
        assert!(buf[25..32].iter().all(|&b| b == 0));
        assert_eq!(buf[32], 0xff);
        assert_eq!(write_dirent64(&mut buf[..31], 7, 1, DT_REG, b"hello"), None);
    }

    #[test]
    fn statfs_layout() {
        assert_eq!(core::mem::size_of::<Statfs>(), 120);
        assert_eq!(core::mem::offset_of!(Statfs, f_fsid), 56);
        assert_eq!(core::mem::offset_of!(Statfs, f_namelen), 64);
        assert_eq!(core::mem::offset_of!(Statfs, f_flags), 80);
        assert_eq!(core::mem::offset_of!(Statfs, f_spare), 88);
    }

    #[test]
    fn modes() {
        assert_eq!(mode_to_dtype(S_IFDIR | 0o755), DT_DIR);
        assert_eq!(mode_to_dtype(S_IFREG), DT_REG);
        assert_eq!(mode_to_dtype(S_IFLNK), DT_LNK);
        assert_eq!(mode_to_dtype(S_IFCHR), DT_CHR);
        assert_eq!(mode_to_dtype(S_IFSOCK), DT_SOCK);
        let d = makedev(1, 3);
        assert_eq!(d, 0x103);
        assert_eq!((dev_major(d), dev_minor(d)), (1, 3));
        let d = makedev(0x12345, 0x6789a);
        assert_eq!((dev_major(d), dev_minor(d)), (0x12345, 0x6789a));
    }
}
